#!/usr/bin/env python3
from pathlib import Path
import base64, hashlib, json, os, subprocess, sys, time
ROOT = Path('/workspace/p1-complete-proof/20261127-p15-mellin-variation-mathlib-probe-v1')
SHA = 'fd9ae7288986c4f7545869cbc62a3415f53eff76b95f533342f1331299cb03dd'
PAYLOAD = ''
run = ROOT / SHA / 'runs' / 'attempt-00000'
old_object = Path('/workspace/blue-member-build/.lake/build/lib/lean/ImbalancedChen/Part3PrimeMellinProfileVariation.olean')
if old_object.exists():
    raise SystemExit('Existing variation object requires reuse inspection before any probe: '+str(old_object))
if run.exists():
    raise SystemExit('Refusing to repeat an existing probe attempt: '+str(run))
raw = base64.b64decode(PAYLOAD)
assert len(raw) == 6717 and hashlib.sha256(raw).hexdigest() == SHA
assert run.parent.resolve() == run.parent
run.mkdir(parents=True, exist_ok=False)
source = run / 'Part3PrimeMellinProfileVariation.lean'
with source.open('xb') as out:
    out.write(raw)
log = run / 'probe.log'
state = '/workspace/blue-build-tools/member-runtime-evidence/state.json'
argv = ['python3', '/workspace/blue-build-tools/serialize_validation_lane.py',
        '--state', state, '--receipt', str(run / 'PROBE_LANE.json'),
        'python3', '/workspace/blue-build-tools/run_guarded.py',
        '--state', state, 'lake', '--no-build', 'env', 'lean', str(source)]
start = time.time()
result = {'schema':'p15_mellin_variation_mathlib_only_probe_v1',
          'source_commit_base':'040d46058821746c69c5183b3f6c22792287c4ba',
          'source_sha256':SHA, 'source_bytes':len(raw),
          'original_source_sha256':'2146552e2b0e5fcbe8a3ef40626e3dc957ce4721b02e026ba699470550276d75',
          'proof_body_unchanged':True, 'project_dependencies':[], 'imports':['Mathlib'],
          'argv':argv, 'cwd':'/workspace/blue-member-build',
          'output_object_requested':False, 'new_owner_accepted':False,
          'whole_P1_5_complete':False}
with log.open('xb') as out:
    p = subprocess.run(argv, cwd='/workspace/blue-member-build', stdout=out, stderr=subprocess.STDOUT)
result.update(exit_code=p.returncode, elapsed_seconds=time.time()-start,
              log_path=str(log), log_bytes=log.stat().st_size,
              log_sha256=hashlib.sha256(log.read_bytes()).hexdigest(),
              probe_passed=p.returncode==0)
with (run/'PROBE_RESULT.json').open('x') as out:
    json.dump(result,out,indent=2,sort_keys=True);out.write('\n')
print(json.dumps(result,sort_keys=True),flush=True)
print(log.read_text(errors='replace')[-16000:],flush=True)
raise SystemExit(p.returncode)
